//! Project-authored, component-level production-compilation tests.
//!
//! Each `<name>.trace` is generated by the Lisp system from a tiny model that
//! causes exactly one p1 -> p2 composition.  The Rust engine runs the same
//! vendored model, and both traces are reduced to their `New production`
//! blocks so startup timing and unrelated trace noise cannot mask the actual
//! composition difference.

use std::fs;
use std::path::PathBuf;

use actr_engine::{run_model, DeviceSetup};

mod common;
use common::{crate_dir, first_diff, meta_value, models_dir, normalize_eol, parse_seed_str};

macro_rules! unit_case {
    ($ident:ident, $name:literal) => {
        #[test]
        fn $ident() {
            if let Err(e) = run_case($name) {
                panic!("{e}");
            }
        }
    };
}

unit_case!(rename_shared, "rename-shared");
unit_case!(rename_different, "rename-different");
unit_case!(goal_dynamic_roundtrip, "goal-dynamic-roundtrip");
unit_case!(goal_dynamic_static, "goal-dynamic-static");
unit_case!(imaginal_dynamic, "imaginal-dynamic");
unit_case!(retrieval_instantiate, "retrieval-instantiate");
unit_case!(safe_bind_output, "safe-bind-output");
unit_case!(union_subtract, "union-subtract");

#[test]
fn duplicate_safe_bind() {
    if let Err(e) = run_case("duplicate-safe-bind") {
        panic!("{e}");
    }
}

#[test]
fn self_composition() {
    if let Err(e) = run_case("self-composition") {
        panic!("{e}");
    }
}

#[test]
fn ppm_slot_order() {
    if let Err(e) = run_case_selected("ppm-slot-order", Some("P4 & P5")) {
        panic!("{e}");
    }
}

fn traces_dir() -> PathBuf {
    crate_dir().join("fixtures").join("compilation-traces")
}

fn run_case(name: &str) -> Result<(), String> {
    run_case_selected(name, None)
}

fn run_case_selected(name: &str, selected_doc: Option<&str>) -> Result<(), String> {
    let root = models_dir();
    if !root.is_dir() {
        return Err(format!(
            "vendored model fixtures not found at {}",
            root.display()
        ));
    }
    let trace_path = traces_dir().join(format!("{name}.trace"));
    let expected =
        fs::read_to_string(&trace_path).map_err(|e| format!("{}: {e}", trace_path.display()))?;
    let meta_path = trace_path.with_extension("meta");
    let meta =
        fs::read_to_string(&meta_path).map_err(|e| format!("{}: {e}", meta_path.display()))?;
    let model = meta_value(&meta, "model")?;
    let seed = parse_seed_str(&meta_value(&meta, "seed")?)?;
    let run_time: f64 = meta_value(&meta, "run")?
        .parse()
        .map_err(|_| format!("{name}: bad run time"))?;

    let actual = run_model(&root, &model, seed, run_time, &DeviceSetup::default())
        .map_err(|e| format!("{name}: engine error: {e}"))?;

    let expected_blocks = select_blocks(composition_blocks(&expected), selected_doc);
    let actual_blocks = select_blocks(composition_blocks(&actual), selected_doc);
    if expected_blocks.is_empty() {
        let expected = result_production(&expected).ok_or_else(|| {
            format!("{name}: Lisp trace has no composition block or result production")
        })?;
        let actual = result_production(&actual).ok_or_else(|| {
            format!(
                "{name}: Rust trace has no composition block or result production; expected {expected}\n{actual}"
            )
        })?;
        if !actual_blocks.is_empty() {
            return Err(format!(
                "{name}: Rust emitted a new production, expected duplicate {expected}"
            ));
        }
        return if expected.eq_ignore_ascii_case(&actual) {
            Ok(())
        } else {
            Err(format!(
                "{name}: duplicate production mismatch: expected {expected}, got {actual}"
            ))
        };
    }
    if expected_blocks.len() != 1 {
        return Err(format!(
            "{name}: Lisp trace has {} composition blocks, expected exactly one:\n{}",
            expected_blocks.len(),
            expected_blocks.join("\n---\n")
        ));
    }
    if actual_blocks.len() != 1 {
        return Err(format!(
            "{name}: Rust trace has {} composition blocks, expected exactly one:\n{}",
            actual_blocks.len(),
            actual_blocks.join("\n---\n")
        ));
    }
    let expected = normalize_eol(&expected_blocks[0]);
    let actual = normalize_eol(&actual_blocks[0]);
    if std::env::var_os("UNIT_DEBUG").is_some() {
        eprintln!("--- expected ---\n{expected}\n--- actual ---\n{actual}");
    }
    if expected == actual {
        Ok(())
    } else {
        let e: Vec<&str> = expected.lines().collect();
        let a: Vec<&str> = actual.lines().collect();
        Err(format!(
            "{name}: composed production mismatch vs {}\n{}",
            trace_path.display(),
            first_diff(&e, &a)
        ))
    }
}

fn select_blocks(blocks: Vec<String>, doc: Option<&str>) -> Vec<String> {
    match doc {
        None => blocks,
        Some(doc) => {
            let needle = format!("\"{}\"", doc.to_ascii_lowercase());
            blocks
                .into_iter()
                .filter(|b| b.to_ascii_lowercase().contains(&needle))
                .collect()
        }
    }
}

/// The existing production named by a duplicate-result composition line.
fn result_production(trace: &str) -> Option<String> {
    trace.lines().find_map(|line| {
        let t = line.trim();
        t.strip_prefix("Result is production ")
            .or_else(|| t.strip_prefix("result is production "))
            .map(str::trim)
            .map(str::to_string)
    })
}

/// Extract every `New production:` block, ending before its parameter dump.
fn composition_blocks(trace: &str) -> Vec<String> {
    let lines: Vec<&str> = trace.lines().collect();
    let mut blocks = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        if lines[i].trim() == "New production:" {
            let mut block = Vec::new();
            i += 1;
            while i < lines.len() {
                let t = lines[i].trim();
                if t.starts_with("Parameters for production")
                    || t.starts_with("Setting previous production")
                    || t.starts_with("Production Compilation process started")
                {
                    break;
                }
                block.push(lines[i]);
                i += 1;
            }
            blocks.push(block.join("\n"));
        } else {
            i += 1;
        }
    }
    blocks
}
